    if not cells:
        return g
    # The examples show a solid rectangular seed; extend occupied seed rows and columns.
    rows = {r for r,c in cells}
    cols = {c for r,c in cells}
    for r in rows:
        for c in range(w):
            if g[r][c] == 0: g[r][c] = 2
    for c in cols:
        for r in range(h):
            if g[r][c] == 0: g[r][c] = 2
    return g
